"""Local replica of check.py without the controller process-guard profile."""
import json, os, subprocess, sys, time
from pathlib import Path
sys.path.insert(0, '/workspace')
from audit import audit

def unique(pairs):
    out = {}
    for k, v in pairs:
        if k in out: raise ValueError("duplicate output key")
        out[k] = v
    return out

def decode(data):
    return json.loads(data.decode("utf-8"), object_pairs_hook=unique,
                      parse_constant=lambda v: (_ for _ in ()).throw(ValueError("nonfinite")))

def run_child(entry, data, argv=None, raw=False, wall=120):
    env = dict(os.environ, PYTHONUNBUFFERED="1", PYTHONDONTWRITEBYTECODE="1",
               PYTHONHASHSEED="0", TMPDIR="/workspace/tmp")
    t0=time.time()
    p = subprocess.run(argv or [sys.executable, "-B", str(entry)], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, timeout=wall)
    dt=time.time()-t0
    if p.returncode != 0:
        raise ValueError("child exited nonzero: %r" % p.stderr[:2000])
    if len(p.stdout) > 64*1024*1024: raise ValueError("stdout cap")
    if len(p.stderr) > 1024*1024: raise ValueError("stderr cap")
    return (p.stdout, dt) if raw else (decode(p.stdout), dt)

def main():
    entry = Path(sys.argv[1] if len(sys.argv)>1 else '/workspace/submission/main.py')
    examples = Path('/workspace/examples')
    ok = True
    for fixture in sorted(examples.glob("*.in.json")):
        expected = decode(fixture.with_name(fixture.name.replace(".in.", ".out.")).read_bytes())
        payload = fixture.read_bytes()
        try:
            request = decode(payload)
        except ValueError:
            request = None
        actual, dt = run_child(entry, payload)
        try:
            audit(request, actual, expected)
            print("PASS json %-24s %.2fs" % (fixture.name, dt))
        except ValueError as exc:
            ok = False
            print("FAIL json %-24s %s" % (fixture.name, exc))
    binary = Path('/workspace/tmp/harness-engine')
    _, dt = run_child(entry, b'', argv=['g++','-O2','-std=c++17',str(entry.parent/'engine.cpp'),'-o',str(binary)], raw=True)
    print("build engine %.2fs" % dt)
    for fixture in sorted(examples.glob('*.in.native')):
        expected = fixture.with_name(fixture.name.replace('.in.', '.out.')).read_bytes()
        actual, dt = run_child(entry, fixture.read_bytes(), argv=[str(binary)], raw=True)
        if actual.split() != expected.split():
            ok = False
            print("FAIL native %-22s\n got %r\n exp %r" % (fixture.name, actual.split()[:20], expected.split()[:20]))
        else:
            print("PASS native %-22s %.2fs" % (fixture.name, dt))
    print("ALL OK" if ok else "FAILURES")
    return 0 if ok else 1

if __name__ == '__main__':
    raise SystemExit(main())
PYEOF
